float genererBruit1D(float valeur) {
    return fract(sin(valeur * 127.1) * 43758.55);
}

vec2 genererBruit2D(vec2 vecteur) {
    return fract(sin(vecteur * 127.1) * 43758.55);
}

mat2 calculerMatriceRotation(float angle) {
    vec4 anglesCoordonnees = angle + vec4(0.0, 1.0, 3.0, 0.0) * 1.57079632679;
    return mat2(cos(anglesCoordonnees.x), cos(anglesCoordonnees.y), cos(anglesCoordonnees.z), cos(anglesCoordonnees.w));
}

vec3 calculerFondAtmospherique(float rayonDistance, float intensiteTransition) {
    vec3 couleurBase = vec3(0.01, 0.02, 0.05);
    vec3 lueurHalogene = vec3(0.09, 0.21, 0.54) * exp(-rayonDistance * 3.5) * intensiteTransition;
    vec3 lueurCentre = vec3(0.4, 0.6, 1.0) * exp(-rayonDistance * 12.0) * (0.04 + 0.96 * intensiteTransition);

    return couleurBase + lueurHalogene + lueurCentre;
}

vec3 calculerTraineeRadiale(vec2 uv, vec2 positionEtoile, float aleatoireTeinte, float transitionProgression, float temps, float indexPoint, float intensiteEffet) {
    float rayonPoint = length(positionEtoile);
    vec2 directionPoint = positionEtoile / max(rayonPoint, 0.001);

    mat2 matriceOrientation = mat2(directionPoint.x, -directionPoint.y, directionPoint.y, directionPoint.x);
    vec2 coordonneesOrien = matriceOrientation * uv;

    float projectionTangente = (rayonPoint + transitionProgression * transitionProgression * 2.6 - coordonneesOrien.x) / (0.005 + transitionProgression * 0.9);

    float masqueEpaisseur = smoothstep(0.0035 + transitionProgression * 0.01, 0.0, abs(coordonneesOrien.y));
    float masqueLongueur = max(0.0, 1.0 - projectionTangente) * step(0.0, projectionTangente);
    float scintillation = 0.6 + 0.4 * sin(temps * 3.0 + indexPoint * 40.0);

    vec3 couleurTrainee = mix(vec3(0.6, 0.8, 1.0), vec3(1.0), aleatoireTeinte);

    return masqueEpaisseur * masqueLongueur * scintillation * couleurTrainee * intensiteEffet;
}

vec3 calculerTraineeVitesse(vec2 uv, float aleatoireOrientation, float aleatoireVitesse, float aleatoireTeinte, float tempsCycle, float intensiteEffet) {
    vec2 coordonneesTournees = calculerMatriceRotation(aleatoireOrientation * 6.28318530718) * uv;

    float progressionFract = fract(aleatoireVitesse + (tempsCycle - 7.0) * (0.5 + genererBruit1D(aleatoireOrientation + 2.0)) * 0.5);
    float projectionVitesse = (progressionFract * progressionFract * 2.2 - coordonneesTournees.x) / (0.12 + progressionFract * 0.8);

    float masqueEpaisseur = smoothstep(0.003 + progressionFract * 0.012, 0.0, abs(coordonneesTournees.y));
    float masqueLongueur = max(0.0, 1.0 - projectionVitesse) * step(0.0, projectionVitesse);
    float masqueFondu = smoothstep(0.0, 0.12, progressionFract) * smoothstep(1.0, 0.75, progressionFract);

    vec3 couleurVitesse = mix(vec3(0.55, 0.75, 1.0), vec3(1.0), aleatoireTeinte);

    return masqueEpaisseur * masqueLongueur * masqueFondu * couleurVitesse * intensiteEffet;
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 resolution = iResolution.xy;
    vec2 uv = (coordFragment - 0.5 * resolution) / resolution.y;
    float temps = iTime;

    uv *= calculerMatriceRotation(0.05 * sin(temps * 0.3));
    float rayonDistance = length(uv);

    float tempsCycle = mod(temps, 15.0);
    float etapeTransition1 = smoothstep(6.0, 7.4, tempsCycle);
    float intensiteTransition = smoothstep(7.0, 8.6, tempsCycle) * (1.0 - smoothstep(13.2, 14.6, tempsCycle));
    float transitionProgression = smoothstep(6.0, 8.6, tempsCycle);

    float intensitePhaseRadiale = max(1.0 - etapeTransition1, etapeTransition1 * (1.0 - smoothstep(7.4, 8.8, tempsCycle))) * 1.5;
    float intensitePhaseVitesse = intensiteTransition * 1.3;

    vec3 couleurAccumulee = calculerFondAtmospherique(rayonDistance, intensiteTransition);

    for (float indexParticule = 0.0; indexParticule < 220.0; indexParticule += 1.0) {
        float identifiantParticule = indexParticule * 1.113;
        float aleatoireTeinte = genererBruit1D(identifiantParticule + 7.0);
        float aleatoireOrientation = genererBruit1D(identifiantParticule);
        float aleatoireVitesse = genererBruit1D(identifiantParticule + 5.0);

        vec2 positionAleatoire = (genererBruit2D(identifiantParticule + vec2(0.0, 3.0)) - 0.5) * 2.6;

        couleurAccumulee += calculerTraineeRadiale(
            uv, 
            positionAleatoire, 
            aleatoireTeinte, 
            transitionProgression, 
            temps, 
            identifiantParticule, 
            intensitePhaseRadiale
        );

        couleurAccumulee += calculerTraineeVitesse(
            uv, 
            aleatoireOrientation, 
            aleatoireVitesse, 
            aleatoireTeinte, 
            tempsCycle, 
            intensitePhaseVitesse
        );
    }

    vec3 couleurCorrigee = pow(couleurAccumulee, vec3(0.85));
    couleurFragment = vec4(couleurCorrigee, 1.0);
}

float genererBruitPseudoAleatoire1D(float valeur) {
    return fract(sin(valeur * 127.1) * 43758.5);
}

float genererBruitLisse1D(float valeur) {
    float indexInferieur = floor(valeur);
    float indexSuperieur = indexInferieur + 1.0;
    float fraction = fract(valeur);
    float interpolationLisse = smoothstep(0.0, 1.0, fraction);

    float valeurInferieure = genererBruitPseudoAleatoire1D(indexInferieur);
    float valeurSuperieure = genererBruitPseudoAleatoire1D(indexSuperieur);

    return mix(valeurInferieure, valeurSuperieure, interpolationLisse);
}

float genererOndeSinusoidale(float phase) {
    return sin(6.28318530718 * phase);
}

float calculerCoucheIntroductive(float tempsCycle, float enveloppeEntree) {
    float basseMontante = genererOndeSinusoidale((25.0 + tempsCycle * tempsCycle * tempsCycle * 0.2546) * tempsCycle + 0.2387 * genererOndeSinusoidale(8.0 * tempsCycle)) * 0.4;
    float subBasseModulee = genererOndeSinusoidale(32.0 * tempsCycle + 0.0796 * genererBruitLisse1D(tempsCycle * 120.0)) * 0.5;
    float souffleTexture = genererBruitLisse1D(tempsCycle * 3000.0) * (0.03 + 0.07 * genererBruitLisse1D(tempsCycle * 15.0));
    float bruitFrequenceVariable = genererBruitLisse1D(tempsCycle * (80.0 + tempsCycle * tempsCycle * tempsCycle * tempsCycle * 0.3858)) * 0.3;

    return (basseMontante + subBasseModulee + souffleTexture + bruitFrequenceVariable) * enveloppeEntree;
}

float calculerImpactSubit(float tempsDepuisImpact, float enveloppeExtinction) {
    return exp(-tempsDepuisImpact * 8.0) * genererOndeSinusoidale((100.0 + enveloppeExtinction * 200.0) * tempsDepuisImpact) * 0.7;
}

float calculerCoucheTransition(float tempsCycle, float ondeResonnante, float enveloppeProgression, float enveloppeTransition) {
    float ondeHarmoniqueGlissante = genererOndeSinusoidale((400.0 + enveloppeProgression * enveloppeProgression * 600.0) * tempsCycle + 0.0477 * genererOndeSinusoidale(140.0 * tempsCycle)) * 0.08;
    float bruitHauteFrequenceProgression = genererBruitLisse1D(tempsCycle * (800.0 + enveloppeProgression * 1500.0)) * 0.15;

    return (ondeResonnante * 0.55 + ondeHarmoniqueGlissante + bruitHauteFrequenceProgression) * enveloppeTransition;
}

float calculerCouchePlateau(float tempsCycle, float ondeResonnante, float enveloppePlateau) {
    float ondeAigueConstante = genererOndeSinusoidale(1200.0 * tempsCycle) * 0.02;
    float souffleCymbales = genererBruitLisse1D(tempsCycle * 4000.0) * 0.05;

    return (ondeAigueConstante + ondeResonnante * 0.4 + souffleCymbales) * enveloppePlateau;
}

vec2 mainSound(int indexEchantillon, float temps) {
    float tempsCycle = mod(temps, 15.0);

    float enveloppeExtinction = smoothstep(6.5, 6.0, tempsCycle);
    float enveloppeEntree = smoothstep(0.0, 6.0, tempsCycle) * enveloppeExtinction;
    float tempsDepuisImpact = max(0.0, tempsCycle - 6.0);

    float enveloppeProgression = smoothstep(6.0, 8.6, tempsCycle);
    float ondeResonnante = genererOndeSinusoidale((35.0 + enveloppeProgression * 25.0) * tempsCycle + 0.6366 * genererBruitLisse1D(tempsCycle * 90.0));

    float enveloppeTransition = smoothstep(6.0, 7.4, tempsCycle) * smoothstep(14.6, 13.2, tempsCycle);
    float enveloppePlateau = smoothstep(7.4, 13.2, tempsCycle) * smoothstep(14.8, 13.2, tempsCycle);

    float signalAudio = 0.0;

    signalAudio += calculerCoucheIntroductive(tempsCycle, enveloppeEntree);
    signalAudio += calculerImpactSubit(tempsDepuisImpact, enveloppeExtinction);
    signalAudio += calculerCoucheTransition(tempsCycle, ondeResonnante, enveloppeProgression, enveloppeTransition);
    signalAudio += calculerCouchePlateau(tempsCycle, ondeResonnante, enveloppePlateau);

    float signalAudioClipper = clamp(signalAudio, -1.0, 1.0);

    return vec2(signalAudioClipper);
}
